mapper.select:


WHERE


			art.id = #{id}


			art.id_site = #{id_site}


ORDER BY art.modified_date DESC
LIMIT 1

SELECT art.id, art.id_site, art.status, art.pause_reason, art.notes, art.cadence, art.start_date, art.end_date, art.keep_cycle, art.recipient_to, art.recipient_cc, art.modified_date, art.modified_by, s.`name` AS site_name, cpn.`name` AS company, sg.`name` AS country, DATE_FORMAT( CONVERT_TZ( art.modified_date,'UTC', tz.value), '%Y-%m-%d %H:%i:%s' ) AS last_updated FROM analytical_report_tracker art JOIN site s ON s.id = art.id_site JOIN company cpn ON cpn.id = s.id_company JOIN site_group sg ON sg.id = s.id_site_group JOIN time_zone tz ON tz.id = s.id_time_zone
AND s.name LIKE CONCAT('%', #{searchKeyword}, '%')
AND sg.id = #{filterCountry}
AND cpn.id = #{filterCompany}
AND s.id = #{filterSite}
AND art.cadence = #{filterCadence}
AND art.status = #{filterStatus}
ORDER BY art.modified_date DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT
	COUNT(art.id)
FROM analytical_report_tracker art
JOIN site s ON s.id = art.id_site
JOIN company cpn ON cpn.id = s.id_company
JOIN site_group sg ON sg.id = s.id_site_group
JOIN time_zone tz ON tz.id = s.id_time_zone


		AND s.name LIKE CONCAT('%', #{searchKeyword}, '%')



		AND sg.id = #{filterCountry}



		AND cpn.id = #{filterCompany}



		AND s.id = #{filterSite}



		AND art.cadence = #{filterCadence}



		AND art.status = #{filterStatus}
